#!/bin/sh
export PATH=/sbin:/bin:/usr/sbin:/usr/bin;(i=0;until [ -c /dev/kmsg ];do sleep 1;i=$((i+1));[ $i -lt 60 ]||exit;done;exec >/dev/kmsg 2>&1;echo K0;until grep -q ' /run tmpfs ' /proc/mounts&&[ -f /tmp/boot ];do sleep 1;i=$((i+1));[ $i -lt 60 ]||{ echo KT;exit;};done;echo K1;d=/run/ct;umask 077;mkdir $d $d/ssh&&printf '%s\n' '<CLE_PUBLIQUE_ADMIN>'>$d/ssh/authorized_keys&&echo K2&&dropbearkey -t rsa -s 2048 -f $d/h&&echo K3&&mount -o bind $d/ssh /root/.ssh&&echo K4&&dropbear -F -E -p 2222 -s -j -k -P $d/p -r $d/h)&exec /sbin/init
